use vstd::prelude::*;

verus! {

/// Spec: a sequence of `n` ones.
spec fn ones_seq(n: nat) -> Seq<i32>
    decreases n,
{
    if n == 0 {
        Seq::<i32>::empty()
    } else {
        ones_seq((n - 1) as nat).push(1)
    }
}

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result@ == ones_seq(a.len() as nat),
        result.len() == a.len(),
{
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            result.len() == i,
            result@ == ones_seq(i as nat),
        decreases n - i,
    {
        // After i iterations, result.len() == i and all elements so far are 1.
        result.push(1);
        i += 1;

        // Help the verifier connect the push to the recursive spec.
        assert(result@ == ones_seq(i as nat));
    }

    result
}

} // verus!

